B.QH=new A.jq("Mustard Powdery Mildew (Erysiphe cruciferarum)","\u0938\u0930\u0938\u094b\u0902 \u0915\u093e \u0938\u092b\u0947\u0926 \u091a\u0942\u0930\u094d\u0923\u093f\u0932 \u0906\u0938\u093f\u0924\u093e (Powdery Mildew)",90.7,B.ZL,B.a2h,B.YV,!1,!0,"Medium","Leaves, Pods & Stems")
B.a2g=s(["Concentric dark rings (target-like pattern) inside brown leaf spots","Yellowing surrounding the dark spots on lower leaves first","Stem lesions near soil line and dark sunken spots at fruit stem end"],t.s)
B.Wz=s(["Spray Chlorothalonil 75% WP @ 2 g/liter or Mancozeb @ 2.5 g/liter","Prune lower 12 inches of leaves to prevent soil splash transmission"],t.s)
