B.a3c=s(["\u0906\u092a\u0915\u0940 \u092e\u093f\u091f\u094d\u091f\u0940 \u0914\u0930 \u092e\u094c\u0938\u092e \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930, \u0917\u0947\u0939\u0942\u0902 \u0914\u0930 \u0938\u0930\u0938\u094b\u0902 \u0915\u0940 \u0916\u0947\u0924\u0940 \u0938\u092c\u0938\u0947 \u0909\u092a\u092f\u0941\u0915\u094d\u0924 \u0930\u0939\u0947\u0917\u0940\u0964 \u0905\u0915\u094d\u091f\u0942\u092c\u0930-\u0928\u0935\u0902\u092c\u0930 \u092e\u0947\u0902 \u092c\u0941\u0935\u093e\u0908 \u0915\u0930\u0947\u0902\u0964\n\n\u26a0\ufe0f \u0938\u0932\u093e\u0939: \u092c\u0941\u0935\u093e\u0908 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092e\u093f\u091f\u094d\u091f\u0940 \u092a\u0930\u0940\u0915\u094d\u0937\u0923 \u091c\u0930\u0942\u0930 \u0915\u0930\u0935\u093e\u090f\u0902\u0964"],t.s)
B.a_G=s(["\u0906\u091c \u0915\u093e \u0924\u093e\u092a\u092e\u093e\u0928 \u0905\u0927\u093f\u0915 \u0939\u0948\u0964 \u0936\u093e\u092e 5-7 \u092c\u091c\u0947 \u0915\u0947 \u092c\u0940\u091a \u0938\u093f\u0902\u091a\u093e\u0908 \u0915\u0930\u0947\u0902 \u2014 \u0907\u0938\u0938\u0947 \u092a\u093e\u0928\u0940 \u0915\u0940 \u092c\u091a\u0924 \u0939\u094b\u0917\u0940 \u0914\u0930 \u092b\u0938\u0932 \u0915\u094b \u091c\u094d\u092f\u093e\u0926\u093e \u092b\u093e\u092f\u0926\u093e \u0939\u094b\u0917\u093e\u0964\n\n\ud83d\udca1 \u091f\u093f\u092a: \u0921\u094d\u0930\u093f\u092a \u0938\u093f\u0902\u091a\u093e\u0908 \u0938\u0947 40% \u092a\u093e\u0928\u0940 \u0915\u0940 \u092c\u091a\u0924 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964"],t.s)
B.YT=s(["\u092a\u0924\u094d\u0924\u093f\u092f\u094b\u0902 \u0915\u093e \u092a\u0940\u0932\u093e \u0939\u094b\u0928\u093e \u0906\u092e\u0924\u094c\u0930 \u092a\u0930 \u0928\u093e\u0907\u091f\u094d\u0930\u094b\u091c\u0928 \u0915\u0940 \u0915\u092e\u0940 \u092f\u093e \u092a\u0924\u094d\u0924\u0940 \u091d\u0941\u0932\u0938\u093e \u0930\u094b\u0917 \u0915\u093e \u0938\u0902\u0915\u0947\u0924 \u0939\u0948\u0964\n\n\u2705 \u0915\u0930\u0947\u0902: \u092f\u0942\u0930\u093f\u092f\u093e \u0915\u093e \u091b\u093f\u0921\u093c\u0915\u093e\u0935 \u0915\u0930\u0947\u0902 (2% \u0918\u094b\u0932) \u092f\u093e Mancozeb \u092b\u092b\u0942\u0902\u0926\u0928\u093e\u0936\u0915 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964\n\u26a0\ufe0f \u091a\u0947\u0924\u093e\u0935\u0928\u0940: \u0905\u0917\u0930 3 \u0926\u093f\u0928\u094b\u0902 \u092e\u0947\u0902 \u0938\u0941\u0927\u093e\u0930 \u0928 \u0939\u094b \u0924\u094b KVK \u0938\u0947 \u0938\u0902\u092a\u0930\u094d\u0915 \u0915\u0930\u0947\u0902\u0964"],t.s)
B.a3A=s(["\u092d\u093e\u0930\u0940 \u092c\u093e\u0930\u093f\u0936 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092f\u0947 \u0915\u093e\u092e \u0915\u0930\u0947\u0902:\n1. \u0916\u0947\u0924 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0928\u093f\u0915\u093e\u0938\u0940 \u0915\u0940 \u091c\u093e\u0902\u091a \u0915\u0930\u0947\u0902\n2. \u0915\u0940\u091f\u0928\u093e\u0936\u0915 \u0915\u093e \u091b\u093f\u0921\u093c\u0915\u093e\u0935 \u0930\u094b\u0915 \u0926\u0947\u0902\n3. \u0915\u091f\u093e\u0908 \u0915\u0947 \u0932\u093f\u090f \u0924\u0948\u092f\u093e\u0930 \u092b\u0938\u0932 \u0915\u094b \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u091c\u0917\u0939 \u0930\u0916\u0947\u0902\n4. \u092e\u0947\u0921\u093c\u092c\u0902\u0926\u0940 \u092e\u091c\u092c\u0942\u0924 \u0915\u0930\u0947\u0902"],t.s)
B.XL=s(["\u0907\u0938 \u0938\u092e\u092f \u0917\u0947\u0939\u0942\u0902 \u0915\u093e \u092d\u093e\u0935 \u20b92200-2400 \u092a\u094d\u0930\u0924\u093f \u0915\u094d\u0935\u093f\u0902\u091f\u0932 \u0939\u0948\u0964 \u092c\u093f\u0915\u094d\u0930\u0940 \u0915\u0947 \u0932\u093f\u090f APMC \u092e\u0902\u0921\u0940 \u091c\u093e\u090f\u0902 \u092f\u093e eNAM \u092a\u094b\u0930\u094d\u091f\u0932 \u092a\u0930 \u0911\u0928\u0932\u093e\u0907\u0928 \u092c\u0947\u091a\u0947\u0902\u0964\n\n\ud83d\udca1 MSP \u0915\u0940 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0915\u0947 \u0932\u093f\u090f PM-KISAN \u092a\u094b\u0930\u094d\u091f\u0932 \u0926\u0947\u0916\u0947\u0902\u0964"],t.s)
B.F0=new A.a_(B.a8j,[B.a3c,B.a_G,B.YT,B.a3A,B.XL],t.VJ)
B.a8t={crop:0,irrigat:1,disease:2,yellow:3,rain:4,market:5,protect:6}
B.Yf=s(["Based on current season and weather, Wheat and Mustard are most suitable for your area. Sow in October-November for best yield.\n\n\u26a0\ufe0f Tip: Get your soil tested before sowing for best results."],t.s)
B.a2F=s(["With today's high temperature, irrigate your crops in the evening (5-7 PM) to minimize evaporation and maximize water absorption.\n\n\ud83d\udca1 Tip: Drip irrigation can save up to 40% water."],t.s)
B.a30=s(["Yellow leaves usually indicate Nitrogen deficiency or Leaf Blight disease.\n\n\u2705 Action: Apply 2% Urea spray or Mancozeb fungicide.\n\u26a0\ufe0f Warning: If no improvement in 3 days, consult your local KVK."],t.s)
B.a3o=s(["Yellowing of leaves can have several causes:\n1. Nitrogen deficiency \u2014 apply Urea\n2. Leaf Blight \u2014 apply fungicide\n3. Waterlogging \u2014 improve drainage\n4. Iron deficiency \u2014 apply Ferrous Sulphate\n\nCheck the pattern of yellowing to identify the exact cause."],t.s)
B.a1w=s(["Before heavy rain:\n1. Check field drainage channels\n2. Stop pesticide spraying\n3. Secure mature/ready-to-harvest crops\n4. Strengthen bunds and ridges\n5. Harvest if crop is ready"],t.s)
B.a1I=s(["Current wheat price: \u20b92200-2400 per quintal. Visit APMC Mandi or use eNAM online portal.\n\n\ud83d\udca1 Check MSP rates at PM-KISAN portal before selling."],t.s)
B.UV=s(["To protect your crop:\n1. Regular field monitoring (2x per week)\n2. Use IPM - Integrated Pest Management\n3. Apply preventive fungicide before monsoon\n4. Maintain field hygiene - remove crop debris\n5. Use certified disease-resistant seeds next season"],t.s)
B.F1=new A.a_(B.a8t,[B.Yf,B.a2F,B.a30,B.a3o,B.a1w,B.a1I,B.UV],t.VJ)
